// Function node: prepend friendly header and return body for email
function toStr(v){
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  try { return JSON.stringify(v); } catch(e) { return String(v); }
}

// extractText / getCandidateFromItem from previous robust function (keeps objects safe)
function extractText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    const parts = value.map(v => extractText(v)).filter(Boolean);
    return parts.join('\n').trim();
  }
  if (typeof value === 'object') {
    const keys = ['summary','text','content','output','result','body','message','parts','choices','data'];
    for (const k of keys) {
      if (value[k]) {
        if (Array.isArray(value[k])) return extractText(value[k]);
        const t = extractText(value[k]);
        if (t) return t;
      }
    }
    for (const k of Object.keys(value)) {
      const t = extractText(value[k]);
      if (t && t.length > 10) return t;
    }
    return toStr(value).replace(/^[\{\[]|[\}\]]$/g,'').trim();
  }
  return '';
}

function getCandidateFromItem(j) {
  const tryKeys = ['summary','combined','combined_summary','final','line','ai_output','text','body','message','result'];
  for (const k of tryKeys) {
    if (j.hasOwnProperty(k) && j[k]) {
      const t = extractText(j[k]);
      if (t) return t;
    }
  }
  if (j.parts && Array.isArray(j.parts)) {
    const p = extractText(j.parts);
    if (p) return p;
  }
  if (j.choices && Array.isArray(j.choices)) {
    const p = extractText(j.choices);
    if (p) return p;
  }
  for (const key of Object.keys(j)) {
    const v = j[key];
    if (typeof v === 'string' && /\d{1,2}:\d{2}\s*-\s/.test(v)) return v.trim();
  }
  let best = '';
  for (const key of Object.keys(j)) {
    const t = extractText(j[key]);
    if (t.length > best.length) best = t;
  }
  return best.trim();
}

// Build groups by sender
const groups = {}; // email => { name, entries: [] }

for (const it of items) {
  const j = it.json || {};
  const email = (j.from_email || j.email || j.sender || 'unknown@example.com').toString().trim();
  const name  = (j.from_name || j.name || '').toString().trim();
  const time  = (j.time_local || j.time || j.date || '').toString().trim();
  const candidate = getCandidateFromItem(j);
  if (!candidate) continue;
  const candidateLines = candidate.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
  const linesToAdd = candidateLines.length === 1 ? [candidateLines[0]] : candidateLines;
  if (!groups[email]) groups[email] = { name, entries: [] };
  for (const l of linesToAdd) {
    const hasTime = /\d{1,2}:\d{2}\s*(am|pm)?\s*-/i.test(l);
    const entryLine = hasTime ? l : (time ? `${time} - ${l}` : l);
    groups[email].entries.push(entryLine);
  }
}

// Compose summaries block
let summariesText = '';
const emails = Object.keys(groups);
for (const email of emails) {
  summariesText += `${email}\n`;
  const entries = groups[email].entries || [];
  for (const e of entries) summariesText += `${e}\n`;
  summariesText += `\n`;
}
if (!summariesText) summariesText = '[no summaries found]';
summariesText = summariesText.trim() + `\n\n-----`;

// Determine recipient name heuristically (from first item or fallback)
let recipientName = 'Chris';
if (items[0] && items[0].json) {
  const j0 = items[0].json;
  const maybe = j0.recipientName || j0.to_name || j0.toName || j0.to || j0.user || j0.owner;
  if (maybe) {
    // extract human name part if it's an email or has angle brackets
    const cleaned = String(maybe).replace(/<.*?>/g,'').replace(/["']/g,'').trim();
    if (cleaned) recipientName = cleaned.split(/[<@]/)[0].trim();
  }
}

// Build friendly header
const header = `Hey ${recipientName},\n\nThis is your summary from the last 24 hours. Have a great day!\n\n`;

// Final email body
const combinedEmailBody = header + summariesText;

// Return both (for debug and flexibility)
return [{ json: { combined_summary: summariesText, combined_email_body: combinedEmailBody, itemCount: items.length } }];
